const cats=['공통교양','MSC','전공'],grades=['A+','A','B+','B','C+','C','D+','D','F','P','NP'],key='graduation-check-v1';
const $=id=>document.getElementById(id);let state={goals:Object.fromEntries(cats.map(c=>[c,null])),courses:[]},filter='전체',editing=null;
function valid(s){return s&&s.goals&&cats.every(c=>s.goals[c]===null||(Number.isFinite(s.goals[c])&&s.goals[c]>=0&&s.goals[c]<=300))&&Array.isArray(s.courses)&&s.courses.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&c.name.trim()&&c.name.length<=100&&cats.includes(c.category)&&grades.includes(c.grade)&&Number.isFinite(c.credits)&&c.credits>0&&c.credits<=30)&&new Set(s.courses.map(c=>c.id)).size===s.courses.length}
try{const s=JSON.parse(localStorage.getItem(key));if(valid(s))state=s}catch{}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',2600)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('saved').textContent='이 브라우저에 자동 저장'}catch{$('saved').textContent='저장 실패 · 기록을 내보내세요';toast('저장 공간을 확인하거나 기록을 내보내세요.')}}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function earned(cat){return state.courses.filter(c=>c.category===cat&&!['F','NP'].includes(c.grade)).reduce((n,c)=>n+c.credits,0)}
function summary(){const area=$('overview');area.replaceChildren();let allSet=true,allDone=true;cats.forEach(cat=>{const goal=state.goals[cat],n=earned(cat),set=goal!==null;allSet&&=set;allDone&&=set&&n>=goal;const box=el('div',undefined,'category'),head=el('div',undefined,'cathead');head.append(el('span',cat),el('span',!set?'기준 미설정':n>=goal?'충족':`${goal-n}학점 남음`,'status'));const num=el('div',undefined,'numbers');num.append(el('span',n),el('small',` / ${set?goal:'—'} 학점`));const bar=el('div',undefined,'bar'),fill=el('div');fill.style.width=(set?(goal===0?100:Math.min(100,n/goal*100)):0)+'%';bar.append(fill);const line=el('div',undefined,'goal'),label=el('label','필요 학점');label.htmlFor='goal-'+cats.indexOf(cat);label.style.margin='0';const input=el('input');Object.assign(input,{id:label.htmlFor,type:'number',min:'0',max:'300',step:'0.5',value:set?goal:'',placeholder:'설정'});input.onchange=()=>{if(!input.checkValidity()){input.reportValidity();return}state.goals[cat]=input.value===''?null:Number(input.value);save();summary()};line.append(label,input);box.append(head,num,bar,line);area.append(box)});$('overall').textContent=!allSet?'기준 설정 필요':allDone?'분류별 학점 충족':'학점 이수 중'}
function render(){summary();$('count').textContent=state.courses.length;$('filters').replaceChildren();['전체',...cats].forEach(cat=>{const b=el('button',cat,'filter'+(filter===cat?' active':''));b.setAttribute('aria-pressed',filter===cat);b.onclick=()=>{filter=cat;render()};$('filters').append(b)});const rows=state.courses.filter(c=>filter==='전체'||c.category===filter);$('courses').replaceChildren();$('empty').hidden=rows.length>0;$('empty').querySelector('strong').textContent=state.courses.length?'이 분류에 등록된 과목이 없습니다':'첫 과목을 기록해 보세요';rows.forEach(c=>{const tr=el('tr');[c.name,c.category,c.credits,c.grade].forEach(v=>tr.append(el('td',v)));const td=el('td',undefined,'actions'),edit=el('button','수정'),del=el('button','삭제');edit.setAttribute('aria-label',c.name+' 수정');del.setAttribute('aria-label',c.name+' 삭제');edit.onclick=()=>{editing=c.id;['name','category','credits','grade'].forEach(k=>$(k).value=c[k]);$('formtitle').textContent='과목 수정';$('submit').textContent='변경 저장하기';$('cancel').hidden=false;$('name').focus()};del.onclick=()=>{if(!confirm(`‘${c.name}’ 과목을 삭제할까요?`))return;state.courses=state.courses.filter(x=>x.id!==c.id);if(editing===c.id)reset();save();render()};td.append(edit,del);tr.append(td);$('courses').append(tr)})}
function reset(){editing=null;$('courseform').reset();$('formtitle').textContent='과목 추가';$('submit').textContent='과목 추가하기';$('cancel').hidden=true}
grades.forEach(g=>$('grade').append(el('option',g)));$('cancel').onclick=reset;
$('courseform').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name){$('name').setCustomValidity('과목명을 입력하세요.');$('name').reportValidity();return}const c={id:editing||crypto.randomUUID(),name,category:$('category').value,credits:Number($('credits').value),grade:$('grade').value};if(editing)state.courses=state.courses.map(x=>x.id===editing?c:x);else state.courses.push(c);save();reset();render();toast('과목을 저장했습니다.');$('name').focus()};$('name').oninput=()=>$('name').setCustomValidity('');
$('export').onclick=()=>{const a=el('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='졸업체크-기록.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const s=JSON.parse(await f.text());if(!valid(s))throw Error();if(state.courses.length&&!confirm('현재 기록을 불러온 기록으로 교체할까요?'))return;state={goals:s.goals,courses:s.courses};reset();save();render();toast('기록을 불러왔습니다.')}catch{toast('올바른 졸업 체크 기록 파일을 선택하세요.')}finally{e.target.value=''}};render();
